import{_ as n,C as c,o as i,c as h,j as e,a as t,E as o,a5 as r}from"./chunks/framework.CINlqUGR.js";const v=JSON.parse('{"title":"日历","description":"","frontmatter":{},"headers":[],"relativePath":"components/calendar.md","filePath":"components/calendar.md","lastUpdated":1787407517000}'),g={name:"components/calendar.md"},s={id:"日历",tabindex:"-1"};function b(u,d,p,x,m,f){const l=c("Badge"),a=c("XhDemo");return i(),h("div",null,[e("h1",s,[d[0]||(d[0]=t("日历 ",-1)),o(l,{type:"info",text:"calendar"}),d[1]||(d[1]=t()),d[2]||(d[2]=e("a",{class:"header-anchor",href:"#日历","aria-label":'Permalink to "日历 <Badge type="info" text="calendar" />"'},"​",-1))]),d[3]||(d[3]=r('<p>一整月（或周 / 月 / 季 / 年）的网格，格子里可以放内容。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>需要看见整段时间的分布：日程、排班、可预约情况。</li><li>需要在格子里显示当天的事件。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>只是录入一个日期：用<a href="./date-picker">日期选择器</a>或<a href="./date-field">日期输入</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>星期名由作者自己渲染，组件一个节点都不替你生成。</li><li><code>isDateUnavailable</code> 与 <code>min</code> / <code>max</code> 都只挡落值不挡聚焦——键盘用户仍能走到不可选的日子上，读屏会念出它不可选。</li><li>支持区间选择、整周选择、固定六行与多月并排。</li><li>周首日、月份名与星期名跟着 <code>locale</code> 走：<code>en-US</code> 周日起、<code>zh-CN</code> 周一起。不给 <code>locale</code> 就跟宿主浏览器语言，读不到才落 <code>en-US</code>——要固定成一种排法就把 <code>locale</code> 显式传上去。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>网格由作者照 weeks / weekDays 自己渲染，组件一个节点都不替你生成</p>',10)),o(a,{src:"calendar/01-basic"}),d[4]||(d[4]=e("h3",{id:"区间选择",tabindex:"-1"},[t("区间选择 "),e("a",{class:"header-anchor",href:"#区间选择","aria-label":'Permalink to "区间选择"'},"​")],-1)),d[5]||(d[5]=e("p",null,"selection-mode=range：第一下落起点、第二下落终点，中间铺一条连续底色",-1)),o(a,{src:"calendar/02-range"}),d[6]||(d[6]=e("h3",{id:"不可选的日子",tabindex:"-1"},[t("不可选的日子 "),e("a",{class:"header-anchor",href:"#不可选的日子","aria-label":'Permalink to "不可选的日子"'},"​")],-1)),d[7]||(d[7]=e("p",null,"isDateUnavailable 与 min / max 都只挡落值不挡聚焦：方向键照样走得过去",-1)),o(a,{src:"calendar/03-unavailable"}),d[8]||(d[8]=e("h3",{id:"格子里放内容",tabindex:"-1"},[t("格子里放内容 "),e("a",{class:"header-anchor",href:"#格子里放内容","aria-label":'Permalink to "格子里放内容"'},"​")],-1)),d[9]||(d[9]=e("p",null,"cell-trigger 的内容全由作者写，日号之外还能塞自己的标记",-1)),o(a,{src:"calendar/04-cell-content"}),d[10]||(d[10]=r('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-calendar&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhCalendarCell</code> <code>XhCalendarCellTrigger</code> <code>XhCalendarGrid</code> <code>XhCalendarGridBody</code> <code>XhCalendarGridHead</code> <code>XhCalendarHeader</code> <code>XhCalendarHeading</code> <code>XhCalendarHeadingMonthTrigger</code> <code>XhCalendarHeadingYearTrigger</code> <code>XhCalendarNextTrigger</code> <code>XhCalendarNextYearTrigger</code> <code>XhCalendarPrevTrigger</code> <code>XhCalendarPrevYearTrigger</code> <code>XhCalendarRoot</code> <code>XhCalendarWeekDay</code> <code>XhCalendarWeekNumber</code> <code>XhCalendarWeekRow</code></td></tr><tr><td>组合式函数</td><td><code>useCalendar</code></td></tr><tr><td>状态机</td><td><code>calendarMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/calendar.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;calendar&quot;</code>：<code>root</code> · <code>header</code> · <code>prev-year-trigger</code> · <code>prev-trigger</code> · <code>next-trigger</code> · <code>next-year-trigger</code> · <code>heading</code> · <code>heading-year-trigger</code> · <code>heading-month-trigger</code> · <strong><code>grid</code></strong> · <code>grid-head</code> · <code>week-day</code> · <code>grid-body</code> · <code>week-row</code> · <code>week-number</code> · <strong><code>cell</code></strong> · <strong><code>cell-trigger</code></strong></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>string | string[]</code></td><td></td><td>选中值，ISO 串。给定即受控：cell 直读 prop，写只发 onValueChange 不落内部值。 单选写成裸串是简写，内部一律归一成数组。</td></tr><tr><td><code>defaultValue</code></td><td><code>string | string[]</code></td><td></td><td></td></tr><tr><td><code>selectionMode</code></td><td><code>CalendarSelectionMode</code></td><td></td><td></td></tr><tr><td><code>focusedValue</code></td><td><code>string</code></td><td></td><td>当前聚焦的那天，ISO 串；它同时决定展示哪个月。给定即受控。 缺省时退回首个选中值，再退回今天。</td></tr><tr><td><code>defaultFocusedValue</code></td><td><code>string</code></td><td></td><td></td></tr><tr><td><code>min</code></td><td><code>string</code></td><td></td><td>可选范围下界（含当天），ISO 串。界外的日子转 aria-disabled，但仍可聚焦。</td></tr><tr><td><code>max</code></td><td><code>string</code></td><td></td><td>可选范围上界（含当天），ISO 串。</td></tr><tr><td><code>isDateUnavailable</code></td><td><code>(value: string) =&gt; boolean</code></td><td></td><td>作者给的不可用判定，收 ISO 串。返回真的日子与界外日子同等对待。</td></tr><tr><td><code>locale</code></td><td><code>string</code></td><td></td><td>决定周首日与月份/星期几的文案，不给按宿主语言，宿主也没有时按 en-US。</td></tr><tr><td><code>timeZone</code></td><td><code>string</code></td><td></td><td>判定「今天」与格式化文案用的时区，默认取宿主本地时区。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>整张日历禁用：翻月按钮转原生 disabled，格子全转 aria-disabled，键盘与点击都不改值。</td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td><td>只读：翻月与移动焦点照常，只是选不动值。</td></tr><tr><td><code>weekdayFormat</code></td><td><code>CalendarWeekdayFormat</code></td><td></td><td>表头缩写粒度，默认 short。</td></tr><tr><td><code>fixedWeeks</code></td><td><code>boolean</code></td><td></td><td>恒渲染六行，默认按当月实际周数。开着能让翻月时网格高度不跳。</td></tr><tr><td><code>view</code></td><td><code>CalendarView</code></td><td></td><td>挑的粒度：天（默认）、月、季度、年。这一档也是「点一格就是选中」的那一档。 格子的值一律是「那段时间的第一天」的 ISO 串，不另立一套值形态—— min/max 比较、区间逻辑、不可用判定、表单出口于是全都原样复用。</td></tr><tr><td><code>activeView</code></td><td><code>CalendarView</code></td><td></td><td>面板此刻铺的是哪一档格子。给定即受控（date-picker 就是这么持有它的）。 它与 view 是两件事：view 是作者要挑的粒度，这个是人钻到了哪一层。 点标题里的年会把它抬到 year，再点一格就往 view 那一档钻回去；到了 view 那一档， 点一格才是选中。缺省即等于 view。</td></tr><tr><td><code>defaultActiveView</code></td><td><code>CalendarView</code></td><td></td><td>非受控初值，缺省同 view。</td></tr><tr><td><code>weekSelection</code></td><td><code>boolean</code></td><td></td><td>周选：点任意一天选中它所在的整周，值落成 [周首日, 周末日]。 只在 view=day 且 selectionMode=range 下生效。</td></tr><tr><td><code>visibleCount</code></td><td><code>number</code></td><td></td><td>并排展示几个连续月，默认 1。区间选择给 2 才好挑——起止常跨月， 一个面板要来回翻页。翻页时整窗一起走一个月，不是各翻各的。 小于 1 的写法回落到 1。</td></tr><tr><td><code>onValueChange</code></td><td><code>(details: CalendarValueChangeDetails) =&gt; void</code></td><td></td><td>value 变化意图回调；受控时是唯一出口，非受控随内部写入一并通知。</td></tr><tr><td><code>onFocusedValueChange</code></td><td><code>(details: CalendarFocusChangeDetails) =&gt; void</code></td><td></td><td>聚焦日变化（方向键、翻页、点了邻月的日子都会发）；受控时是唯一出口。</td></tr><tr><td><code>onActiveViewChange</code></td><td><code>(details: CalendarViewChangeDetails) =&gt; void</code></td><td></td><td>面板钻到了哪一层（点标题钻上、点格子钻下都会发）；受控时是唯一出口。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>value-change</code></td><td><code>CalendarValueChangeDetails</code></td><td>选中集合变化；detail 为 <code>{ value: string[] }</code></td></tr><tr><td><code>focused-value-change</code></td><td><code>CalendarFocusChangeDetails</code></td><td>聚焦日变化；detail 为 <code>{ focusedValue: string }</code></td></tr><tr><td><code>active-view-change</code></td><td><code>CalendarViewChangeDetails</code></td><td>钻到了另一层；detail 为 <code>{ activeView: &#39;day&#39;|&#39;month&#39;|&#39;quarter&#39;|&#39;year&#39; }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhCalendarRoot</code></td><td><code>default</code></td><td><code>CalendarRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>idle</code></p><p><strong>事件</strong>：<code>VALUE.SET</code> · <code>CELL.SELECT</code> · <code>FOCUS.SET</code> · <code>VIEW.SET</code> · <code>HOVER.SET</code> · <code>HOVER.CLEAR</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useCalendar</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>string[]</code></td><td>选中集合，ISO 串；形状不随模式变。</td></tr><tr><td><code>selectionMode</code></td><td><code>CalendarSelectionMode</code></td><td></td></tr><tr><td><code>focusedValue</code></td><td><code>string</code></td><td>生效的聚焦日（三路收口后的结果），恒非空。</td></tr><tr><td><code>panels</code></td><td><code>CalendarPanel[]</code></td><td>并排展示的面板，长度即 visibleCount。作者照它渲染几张网格。</td></tr><tr><td><code>visibleMonth</code></td><td><code>{ year: number, month: number, startValue: string }</code></td><td>首个面板的展示月：年、月（1-12）、月首日 ISO。多面板时是最左那个。</td></tr><tr><td><code>weeks</code></td><td><code>CalendarDay[][]</code></td><td>首个面板的日期矩阵。多面板请改用 panels。</td></tr><tr><td><code>weekDays</code></td><td><code>CalendarWeekDay[]</code></td><td>七列表头，作者照它渲染 week-day。</td></tr><tr><td><code>headingLabel</code></td><td><code>string</code></td><td>首个面板的标题文案（如 2024年2月）。多面板请改用 panels。</td></tr><tr><td><code>view</code></td><td><code>CalendarView</code></td><td>作者要挑的粒度。</td></tr><tr><td><code>activeView</code></td><td><code>CalendarView</code></td><td>面板此刻铺的是哪一档格子。等于 view 时点一格就是选中，粗过 view 时点一格是往下钻。</td></tr><tr><td><code>headingOrder</code></td><td><code>readonly (&#39;year&#39; | &#39;month&#39;)[]</code></td><td>标题里年与月在这个语言里的先后（zh-CN 是年在前，en-US 是月在前）。 手写标记时照它摆两个钮的顺序，标题读起来才顺。</td></tr><tr><td><code>canZoomOutYear</code></td><td><code>boolean</code></td><td>点标题里的年钻不钻得上去：年视图已到顶，钻不上去。</td></tr><tr><td><code>canZoomOutMonth</code></td><td><code>boolean</code></td><td>点标题里的月钻不钻得上去：只有日视图有月这一截。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>isSelected</code></td><td><code>(value: string) =&gt; boolean</code></td><td></td></tr><tr><td><code>isUnavailable</code></td><td><code>(value: string) =&gt; boolean</code></td><td>界外或作者判定不可用。禁用的日历下恒为真。</td></tr><tr><td><code>canGoPrev</code></td><td><code>boolean</code></td><td>上一页是否还有可看的日子（整张禁用或整页都在 min 之前即为假）。</td></tr><tr><td><code>canGoNext</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>canGoPrevYear</code></td><td><code>boolean</code></td><td>大步翻（« / »）此刻能不能按。判据同上，只是步长换成大步。</td></tr><tr><td><code>canGoNextYear</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>setValue</code></td><td><code>(next: string[]) =&gt; void</code></td><td></td></tr><tr><td><code>select</code></td><td><code>(value: string) =&gt; void</code></td><td></td></tr><tr><td><code>focus</code></td><td><code>(value: string) =&gt; void</code></td><td>改写聚焦日；跨月会连带换掉展示月。</td></tr><tr><td><code>setActiveView</code></td><td><code>(next: CalendarView) =&gt; void</code></td><td>直接钻到某一层。</td></tr><tr><td><code>goToPrevMonth</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>goToNextMonth</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>goToPrevYear</code></td><td><code>() =&gt; void</code></td><td>大步翻：日视图走一年，月/季度走十年，年视图走一百年。</td></tr><tr><td><code>goToNextYear</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getHeaderProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getPrevYearTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getPrevTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getNextTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getNextYearTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getHeadingProps</code></td><td><code>(props?: CalendarPanelProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getHeadingYearTriggerProps</code></td><td><code>(props?: CalendarPanelProps) =&gt; T[&#39;button&#39;]</code></td><td>标题里年那一截，点它钻到十年格。年视图下已到顶，转原生 disabled。</td></tr><tr><td><code>getHeadingMonthTriggerProps</code></td><td><code>(props?: CalendarPanelProps) =&gt; T[&#39;button&#39;]</code></td><td>标题里月那一截，点它钻到月格。不在日视图时带 hidden（那一层没有月这一截）。</td></tr><tr><td><code>getGridProps</code></td><td><code>(props?: CalendarPanelProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getGridHeadProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getWeekDayProps</code></td><td><code>(props: CalendarWeekDayProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getGridBodyProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getWeekRowProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getWeekNumberProps</code></td><td><code>(props: CalendarWeekNumberProps) =&gt; T[&#39;element&#39;]</code></td><td>周序号格：行首那一列，语义上是这一行的表头（role=rowheader）。</td></tr><tr><td><code>getWeekNumberText</code></td><td><code>(props: CalendarWeekNumberProps) =&gt; string</code></td><td>这一行该显示的周序号文字。两个适配器都拿它填文本，保证同构。</td></tr><tr><td><code>getCellProps</code></td><td><code>(props: CalendarCellProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getCellTriggerProps</code></td><td><code>(props: CalendarCellProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/dialog-modal/examples/datepicker-dialog/#kbd_label" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>focus outside the grid</td><td>整张网格只占一个 Tab 位：焦点进入聚焦日那一格</td></tr><tr><td><code>ArrowLeft</code></td><td>focus in grid</td><td>焦点前移一天；越过月首即翻到上一月并落在那一天。粗粒度视图里走一格（一个月 / 一季 / 一年）</td></tr><tr><td><code>ArrowRight</code></td><td>focus in grid</td><td>焦点后移一天；越过月末即翻到下一月并落在那一天。粗粒度视图里走一格</td></tr><tr><td><code>ArrowUp</code></td><td>focus in grid</td><td>焦点上移一周（减七天），跨月照样翻页。粗粒度视图里上移一行</td></tr><tr><td><code>ArrowDown</code></td><td>focus in grid</td><td>焦点下移一周（加七天），跨月照样翻页。粗粒度视图里下移一行</td></tr><tr><td><code>Home</code></td><td>focus in grid</td><td>焦点移到本周第一天；周首日随 locale 变。粗粒度视图里移到本行头一格</td></tr><tr><td><code>End</code></td><td>focus in grid</td><td>焦点移到本周最后一天。粗粒度视图里移到本行末一格</td></tr><tr><td><code>PageUp</code></td><td>focus in grid</td><td>退一个月，日号不变（月末日被目标月夹住：3 月 31 日退成 2 月 29 日）。粗粒度视图里退一整页</td></tr><tr><td><code>PageDown</code></td><td>focus in grid</td><td>进一个月，日号不变。粗粒度视图里进一整页</td></tr><tr><td><code>Shift+PageUp</code></td><td>focus in grid</td><td>退一年；粗粒度视图里退十页</td></tr><tr><td><code>Shift+PageDown</code></td><td>focus in grid</td><td>进一年；粗粒度视图里进十页</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>focus in grid, 聚焦日可用且非只读</td><td>选中聚焦日：单选替换、多选切换、区间先落起点再落终点。还没钻到 view 那一档时这一下是往下钻一层</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>grid</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>grid</code></td><td><code>aria-labelledby</code></td><td><code>heading</code> 部件的 id</td></tr><tr><td><code>grid</code></td><td><code>aria-multiselectable</code></td><td>&#39;false&#39; | &#39;true&#39;</td></tr><tr><td><code>grid</code></td><td><code>aria-readonly</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>grid</code></td><td><code>role</code></td><td>&#39;grid&#39;</td></tr><tr><td><code>grid-head</code></td><td><code>role</code></td><td>&#39;rowgroup&#39;</td></tr><tr><td><code>week-day</code></td><td><code>aria-label</code></td><td>meta?.long</td></tr><tr><td><code>week-day</code></td><td><code>role</code></td><td>&#39;columnheader&#39;</td></tr><tr><td><code>grid-body</code></td><td><code>role</code></td><td>&#39;rowgroup&#39;</td></tr><tr><td><code>week-row</code></td><td><code>role</code></td><td>&#39;row&#39;</td></tr><tr><td><code>week-number</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>week-number</code></td><td><code>role</code></td><td>&#39;rowheader&#39;</td></tr><tr><td><code>cell</code></td><td><code>aria-selected</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>cell</code></td><td><code>role</code></td><td>&#39;gridcell&#39;</td></tr><tr><td><code>cell-trigger</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>cell-trigger</code></td><td><code>aria-label</code></td><td>cellLabelFormatter.format(state.date.toDate(timeZone)) | undefined</td></tr><tr><td><code>cell-trigger</code></td><td><code>role</code></td><td>&#39;button&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/calendar.css</code> 按部件选择：<code>[data-scope=&quot;calendar&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>prev-year-trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>prev-trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>next-trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>next-year-trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>heading</code></td><td><code>data-index</code></td><td>panelOf(panel).index</td></tr><tr><td><code>heading</code></td><td><code>data-view</code></td><td>context.get(&#39;activeView&#39;)</td></tr><tr><td><code>heading-year-trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>heading-year-trigger</code></td><td><code>data-index</code></td><td>panelOf(panel).index</td></tr><tr><td><code>heading-year-trigger</code></td><td><code>data-view</code></td><td>context.get(&#39;activeView&#39;)</td></tr><tr><td><code>heading-month-trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>heading-month-trigger</code></td><td><code>data-index</code></td><td>panelOf(panel).index</td></tr><tr><td><code>heading-month-trigger</code></td><td><code>data-view</code></td><td>context.get(&#39;activeView&#39;)</td></tr><tr><td><code>grid</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>grid</code></td><td><code>data-index</code></td><td>panelOf(panel).index</td></tr><tr><td><code>grid</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>grid</code></td><td><code>data-view</code></td><td>context.get(&#39;activeView&#39;)</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-calendar-cell-bg-hover</code> · <code>--xh-calendar-cell-bg-selected</code> · <code>--xh-calendar-cell-fg</code> · <code>--xh-calendar-cell-fg-outside</code> · <code>--xh-calendar-cell-fg-selected</code> · <code>--xh-calendar-cell-font-size</code> · <code>--xh-calendar-cell-gap</code> · <code>--xh-calendar-cell-radius</code> · <code>--xh-calendar-cell-size</code> · <code>--xh-calendar-gap</code> · <code>--xh-calendar-grid-gap</code> · <code>--xh-calendar-header-gap</code> · <code>--xh-calendar-heading-fg</code> · <code>--xh-calendar-heading-font-size</code> · <code>--xh-calendar-heading-font-weight</code> · <code>--xh-calendar-heading-trigger-fg-hover</code> · <code>--xh-calendar-heading-trigger-px</code> · <code>--xh-calendar-heading-trigger-radius</code> · <code>--xh-calendar-icon-size</code> · <code>--xh-calendar-nav-bg</code> · <code>--xh-calendar-nav-bg-hover</code> · <code>--xh-calendar-nav-fg</code> · <code>--xh-calendar-nav-radius</code> · <code>--xh-calendar-nav-size</code> · <code>--xh-calendar-period-gap</code> · <code>--xh-calendar-period-py</code> · <code>--xh-calendar-range-bg</code> · <code>--xh-calendar-row-gap</code> · <code>--xh-calendar-today-border</code> · <code>--xh-calendar-week-day-fg</code> · <code>--xh-calendar-week-day-font-size</code> · <code>--xh-calendar-week-day-font-weight</code> · <code>--xh-calendar-week-day-h</code> · <code>--xh-calendar-week-number-fg</code> · <code>--xh-calendar-week-number-font-size</code> · <code>--xh-calendar-week-number-w</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>格子里放<a href="./badge">徽标</a>或一小段<a href="./typography">排印</a>；外面套<a href="./card">卡片</a>。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>今天要有明显标记，且与&quot;选中&quot;区分开。</li><li>格子里的内容超出时收起来，别让某一行比别的行高很多。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>不可选的日子连焦点都到不了：键盘用户无从知道那里有什么。</li><li>用它当日期输入框。</li></ul>',45))])}const w=n(g,[["render",b]]);export{v as __pageData,w as default};
